var n=`0293-priganice`;var t=`world-0293`;var o=`ME`;var a=`southern-europe`;var s=4;var r=26;var g={en:`Priganice`,ua:`Приганіце`};var l={en:`A traditional Montenegro dish made with all-purpose flour, plain yogurt, chicken egg, baking powder. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Чорногорія. Основні інгредієнти: пшеничне борошно універсальне, натуральний йогурт, куряче яйце, розпушувач тіста. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`all-purpose-flour`,330,`g`],[`plain-yogurt`,200,`g`],[`chicken-egg`,1,`pcs`],[`baking-powder`,10,`g`],[`table-salt`,3,`g`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 15 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 15 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:15,i:[[`sunflower-oil`,500,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`honey`,90,`g`],[`farmer-cheese`,140,`g`]]}];var u={slug:n,id:t,country:`ME`,region:a,servings:4,minutes:26,title:g,text:l,steps:d};export{o as country,u as default,t as id,r as minutes,a as region,s as servings,n as slug,d as steps,l as text,g as title};